// lib/mockups.ts — realistic garment mockups (generated by tools/mockups/generate_tee_mockups.py).
// Geometry here mirrors the generator. Logical space is the designer's 500x500 canvas.
import type { Product } from "@/lib/types";

export type TeeColor = "white" | "ash" | "black" | "navy" | "royal" | "forest" | "red" | "maroon" | "sand";

/** Every garment colour the store can show, in the order the pickers list them. `name` is what goes on the product. */
export const TEE_COLOR_LIST: { key: TeeColor; name: string; hex: string }[] = [
  { key: "white", name: "White", hex: "#F7F7F5" },
  { key: "black", name: "Black", hex: "#181918" },
  { key: "ash", name: "Ash", hex: "#ABAEAC" },
  { key: "navy", name: "Navy", hex: "#1C2A4C" },
  { key: "royal", name: "Royal Blue", hex: "#2654AA" },
  { key: "forest", name: "Forest Green", hex: "#224D34" },
  { key: "red", name: "Red", hex: "#BE262D" },
  { key: "maroon", name: "Maroon", hex: "#641A26" },
  { key: "sand", name: "Sand", hex: "#D6C4A4" },
];
export const TEE_COLOR_NAMES = TEE_COLOR_LIST.map((c) => c.name);
export const teeColorHex = (name?: string | null): string | null => {
  const key = teeColorKey(name);
  return key ? (TEE_COLOR_LIST.find((c) => c.key === key)?.hex ?? null) : null;
};
export type SymbolTone = "auto" | "white" | "black" | "green";

export const MONO_RATIO = 328 / 389; // height / width of the NE monogram files

/** Where customers may place artwork on the front of the tee. */
export const TEE_PRINT_AREA = { x: 140, y: 110, width: 220, height: 300 };
/** Default NE symbol: small, on the wearer's left chest (the right side as you look at the shirt). */
export const SYMBOL_DEFAULT = { x: 298, y: 127, width: 24 };
export const SYMBOL_MIN = 10;
export const SYMBOL_MAX = 120;

/** How strongly the white highlight layer shows on each fabric colour. */
const LIGHT_OPACITY: Record<TeeColor, number> = { white: 0, ash: 0.1, black: 0.55, navy: 0.4, royal: 0.3, forest: 0.4, red: 0.25, maroon: 0.4, sand: 0.05 };
/** Symbol colour chosen automatically for each garment colour. */
const AUTO_TONE: Record<TeeColor, Exclude<SymbolTone, "auto">> = { white: "green", ash: "black", black: "white", navy: "white", royal: "white", forest: "white", red: "white", maroon: "white", sand: "black" };

/** Map a colour name from the admin (White, Jet Black, Heather Ash...) to a mockup colour. */
export function teeColorKey(name?: string | null): TeeColor | null {
  const n = (name ?? "").toLowerCase().trim();
  if (!n) return null;
  const exact = TEE_COLOR_LIST.find((c) => c.name.toLowerCase() === n || c.key === n);
  if (exact) return exact.key;
  if (n.includes("white")) return "white";
  if (n.includes("black")) return "black";
  if (n.includes("ash") || n.includes("grey") || n.includes("gray") || n.includes("heather")) return "ash";
  if (n.includes("navy")) return "navy";
  if (n.includes("royal") || n.includes("blue")) return "royal";
  if (n.includes("forest") || n.includes("green")) return "forest";
  if (n.includes("maroon") || n.includes("burgundy") || n.includes("wine")) return "maroon";
  if (/\bred\b/.test(n)) return "red";
  if (n.includes("sand") || n.includes("beige") || n.includes("cream")) return "sand";
  return null;
}

export type GarmentBase = "tee" | "cap";
/** Where customers may place artwork on the front of the cap (500-unit designer space). */
export const CAP_PRINT_AREA = { x: 175, y: 166, width: 150, height: 90 };
export const printAreaFor = (base: GarmentBase) => (base === "cap" ? CAP_PRINT_AREA : TEE_PRINT_AREA);

/** Which generated mockup a product uses: tees and caps with no photo of their own do; anything else (or a product with its own photo) does not. */
export function mockupBase(product: Pick<Product, "category" | "images">): GarmentBase | null {
  const base = product.category === "T-Shirts" ? "tee" : product.category === "Caps" ? "cap" : null;
  if (!base) return null;
  const first = product.images[0];
  return !first || first.startsWith("/mockups/") ? base : null;
}

/** True when this product has no photo of its own and should use the generated tee mockups. */
export function usesTeeMockup(product: Pick<Product, "category" | "images">): boolean {
  return mockupBase(product) === "tee";
}

export type TeeSide = "front" | "back";

export function garmentLayers(base: GarmentBase, color: TeeColor, side: TeeSide = "front") {
  const name = base === "cap" ? "cap" : "tee";
  const b = side === "back" && base === "tee" ? "back-" : "";
  return {
    bare: `/mockups/${name}-${b}bare-${color}.png`,
    shade: `/mockups/${name}-${b}shade.png`,
    light: `/mockups/${name}-${b}light.png`,
    lightOpacity: LIGHT_OPACITY[color],
  };
}

export const teeLayers = (color: TeeColor, side: TeeSide = "front") => garmentLayers("tee", color, side);

export function symbolSrc(tone: SymbolTone, color: TeeColor): string {
  const t = tone === "auto" ? AUTO_TONE[color] : tone;
  return { white: "/brand/ne-monogram-white.png", black: "/brand/ne-monogram-black.png", green: "/brand/ne-monogram.png" }[t];
}

/** The picture to show for a product in the shop, product page and cart. */
export function productImage(product: Pick<Product, "category" | "images" | "preset">, colorName?: string | null, withSymbol = true): string | null {
  const key0 = teeColorKey(colorName);
  const previews = product.preset?.previews;
  if (previews) {
    const own = (key0 && previews[key0]) || Object.values(previews)[0];
    if (own?.front) return own.front;
  }
  const first = product.images[0];
  if (first && !first.startsWith("/mockups/")) return first;
  const base = mockupBase(product);
  if (!base) return null;
  const key = teeColorKey(colorName) ?? "white";
  return base === "cap" ? `/mockups/cap-${key}.png` : `/mockups/tee-${key}${withSymbol ? "-symbol" : ""}.png`;
}
